using DitaStudio.Core.Model;
using DitaStudio.Core.Validation;

namespace CompanyRules;

public sealed class NoTodoRule : IValidationRulePlugin
{
    public string Name => "Нет пометок TODO";

    public IEnumerable<ValidationIssue> Check(DitaDocument document)
    {
        foreach (var node in document.Root.DescendantsAndSelf())
        {
            if (node.Kind == NodeKind.Text && node.Value.Contains("TODO", StringComparison.Ordinal))
            {
                yield return new ValidationIssue(IssueSeverity.Error,
                    "В тексте осталась пометка TODO", node.Parent, document.FilePath);
            }
        }
    }
}

using System.Text;
using DitaStudio.Core.IO;
using DitaStudio.Core.Project;
using DitaStudio.Core.Publishing;

namespace CompanyRules;

public sealed class PlainTextFormat : IPublishFormatPlugin
{
    public string Name => "Простой текст";

    public string FileExtension => "txt";

    public void Publish(DitaProject project, string mapPath, PublishOptions options, string outputPath)
    {
        var tree = MapTree.Build(project, mapPath, node => PublishFilter.IsIncluded(node, options));
        var sb = new StringBuilder();
        foreach (var item in tree.PublicationOrderWithHeadings)
        {
            sb.AppendLine(item.Title.ToUpperInvariant());
            if (item.TargetPath is not null)
            {
                var doc = RefResolver.ExpandConrefs(project, project.GetDocument(item.TargetPath));
                sb.AppendLine(doc.Root.FirstElement("shortdesc")?.InnerText.Trim());
            }

            sb.AppendLine();
        }

        AtomicFile.WriteAllText(outputPath, sb.ToString(), new UTF8Encoding(false));
    }
}

using DitaStudio.Core.Model;
using DitaStudio.Presentation.Plugins;
using DitaStudio.Presentation.Services;

namespace CompanyRules;

public sealed class MarkDraftCommand : IAuthorCommandPlugin
{
    public string Name => "Пометить блок как черновик";

    public void Execute(IDocumentView pane)
    {
        if (pane.Author.CurrentNode is not { } node)
        {
            throw new InvalidOperationException("Поставьте курсор в блок.");
        }

        pane.PushUndo(Name);
        node.SetAttribute("status", "new");
        node.SetAttribute("rev", "draft");
    }
}
